def e(value):
    return escape(str(value), quote=True)


class Page:
    def __init__(self, language, guide=False):
        self.language = language
        self.fr = language == "fr"
        self.guide = guide
        self.assets = "../assets/" if self.fr else "assets/"
        self.manifest = {item["file"]: item for item in json.loads(
            (SITE / "assets/screenshots/manifest.json").read_text(encoding="utf-8"))["images"]}

    def t(self, en, fr):
        return fr if self.fr else en

    def doc(self, anchor="start"):
        return f"guide.html#{anchor}"

    def link(self, label, href, cls="text-link"):
        return f'<a class="{e(cls)}" href="{e(href)}">{e(label)} <span aria-hidden="true">↗</span></a>'

    def figure(self, name, en, fr, hero=False, image_id=None):
        alt = self.t(en, fr)
        info = self.manifest[name + ".webp"]
        width, height = info["size"]
        identity = f' id="{image_id}"' if image_id else ""
        priority = 'fetchpriority="high" loading="eager"' if hero else 'loading="lazy" decoding="async"'
        return f'''<figure class="{'hero-frame' if hero else 'screenshot'}">
<button class="shot-button" type="button" data-lightbox aria-label="{e(self.t('Enlarge screenshot: ', 'Agrandir la capture : ') + alt)}">
<img{identity} src="{self.assets}screenshots/{name}.webp" width="{width}" height="{height}" alt="{e(alt)}" {priority}></button>
<figcaption><span{' id="theme-caption"' if image_id == 'theme-preview' else ''}>{e(alt)}</span><span class="enlarge" aria-hidden="true">{self.t('View full size', 'Agrandir')} ↗</span></figcaption></figure>'''

    def block(self, label, code):
        return f'''<div class="code-block"><div class="code-toolbar"><span>{e(label)}</span><button type="button" class="copy-code" aria-live="polite">{self.t('Copy', 'Copier')}</button></div><pre><code>{e(code)}</code></pre></div>'''

    def header(self):
        main = "index.html" if self.guide else ""
        filename = "guide.html" if self.guide else "index.html"
        en = "../" + filename if self.fr else filename
        fr = filename if self.fr else "fr/" + filename
        gh = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 .8a11.2 11.2 0 0 0-3.54 21.82c.56.1.77-.24.77-.54v-2.1c-3.13.68-3.8-1.33-3.8-1.33-.5-1.3-1.25-1.65-1.25-1.65-1.02-.7.08-.68.08-.68 1.13.08 1.72 1.16 1.72 1.16 1 1.72 2.63 1.22 3.27.93.1-.73.4-1.22.71-1.5-2.5-.29-5.13-1.25-5.13-5.57 0-1.23.44-2.24 1.16-3.03-.12-.28-.5-1.43.1-2.99 0 0 .95-.3 3.08 1.15a10.7 10.7 0 0 1 5.6 0c2.13-1.45 3.07-1.15 3.07-1.15.62 1.56.23 2.71.12 3a4.4 4.4 0 0 1 1.15 3.02c0 4.33-2.63 5.28-5.14 5.56.4.35.76 1.04.76 2.1v3.08c0 .3.2.65.77.54A11.2 11.2 0 0 0 12 .8Z"/></svg>'
        return f'''<a class="skip-link" href="#main">{self.t('Skip to content', 'Aller au contenu')}</a>
<header class="site-header" id="top"><div class="wrap header-inner">
<a class="brand" href="index.html" aria-label="{self.t('CyUI home', 'Accueil CyUI')}"><img src="{self.assets}mark.svg" width="34" height="34" alt=""><span>Cy<span>UI</span></span></a>
<nav class="header-nav" id="main-nav" aria-label="{self.t('Main navigation', 'Navigation principale')}">
<a href="{main}#editors">{self.t('Features', 'Fonctionnalités')}</a><a href="{main}#modules">Modules</a><a href="{main}#integrations">{self.t('Integrations', 'Intégrations')}</a><a href="guide.html">{self.t('Documentation', 'Documentation')}</a><a href="{main}#download">{self.t('Downloads', 'Téléchargements')}</a></nav>
<div class="header-actions"><nav class="language" aria-label="{self.t('Language', 'Langue')}"><a href="{en}" data-language="en" lang="en" hreflang="en" {'aria-current="page"' if not self.fr else ''} aria-label="English">EN</a><a href="{fr}" data-language="fr" lang="fr" hreflang="fr" {'aria-current="page"' if self.fr else ''} aria-label="Français">FR</a></nav>
<a class="button github small" href="{REPO}">{gh}<span>GitHub</span><span aria-hidden="true">↗</span></a>
<a class="button primary small" href="{main}#download">{self.t('Try the demo', 'Essayer la démo')} <span aria-hidden="true">↓</span></a></div>
<button class="menu-toggle" type="button" aria-label="{self.t('Toggle navigation', 'Ouvrir ou fermer la navigation')}" aria-controls="main-nav" aria-expanded="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button></div></header>'''

    def footer(self):
        return f'''<footer class="site-footer"><div class="wrap"><div class="footer-inner"><a class="brand" href="index.html"><img src="{self.assets}mark.svg" width="26" height="26" alt=""><span>Cy<span>UI</span></span></a><nav class="footer-links" aria-label="{self.t('Footer', 'Pied de page')}"><a href="guide.html">Documentation</a><a href="{RELEASE}">{self.t('Releases', 'Versions')}</a><a href="{REPO}">GitHub</a><a href="{REPO}/blob/main/LICENSE">MIT</a><a href="#top">{self.t('Back to top', 'Retour en haut')} ↑</a></nav></div><p class="footer-note"><span>© 2026 CyUI · Cyberalien</span><span>{self.t('Built on Dear ImGui. CyUI is MIT licensed; dependencies retain their own notices.', 'Basé sur Dear ImGui. CyUI est sous licence MIT ; les dépendances conservent leurs propres mentions.')}</span></p></div></footer>'''

    def dialog(self):
        return f'''<dialog class="lightbox" id="image-dialog" aria-labelledby="image-caption"><div class="lightbox-panel"><div class="lightbox-toolbar"><span id="image-caption"></span><button class="lightbox-close" type="button" aria-label="{self.t('Close image', 'Fermer l’image')}">×</button></div><img class="lightbox-image" alt=""><div class="lightbox-bottom"><button class="lightbox-nav" type="button" data-previous aria-label="{self.t('Previous screenshot', 'Capture précédente')}">←</button><span class="lightbox-counter" aria-live="polite"></span><button class="lightbox-nav" type="button" data-next aria-label="{self.t('Next screenshot', 'Capture suivante')}">→</button><span>{self.t('Esc to close', 'Échap pour fermer')}</span></div></div></dialog>'''

    def section_head(self, number, label, en_title, fr_title, en_text, fr_text):
        return f'''<div class="section-head"><div><p class="eyebrow">{number} / {e(label)}</p><h2>{e(self.t(en_title, fr_title))}</h2></div><p>{e(self.t(en_text, fr_text))}</p></div>'''

    def image_card(self, name, en_alt, fr_alt, en_title, fr_title, en_text, fr_text, anchor):
        return f'''<article class="image-card">{self.figure(name, en_alt, fr_alt)}<h3>{e(self.t(en_title,fr_title))}</h3><p>{e(self.t(en_text,fr_text))}</p>{self.link(self.t('Explore the guide','Découvrir le guide'), self.doc(anchor))}</article>'''

    def main_content(self):
        t = self.t
        chapters = [("foundation",t("Foundation","Fondation")),("editors",t("Editor tools","Outils d’édition")),("graphs",t("Graphs","Graphes")),("audio",t("Audio & data","Audio et données")),("code",t("Code","Code")),("media",t("Media","Médias")),("modules","Modules"),("integrations",t("Integrations","Intégrations")),("download",t("Get started","Commencer"))]
        parts = [f'''<main id="main"><section class="hero" aria-labelledby="hero-title"><div class="wrap"><div class="hero-intro"><div><p class="eyebrow">{t('Modular Dear ImGui library','Bibliothèque modulaire Dear ImGui')}</p><h1 id="hero-title">Cy<span>UI</span></h1></div><p class="hero-lead">{t('Build desktop tools with a shared UI foundation. Themed widgets, visual editors and optional modules for C++ and Python.','Créez des outils de bureau sur une base d’interface commune. Widgets thématisés, éditeurs visuels et modules au choix pour C++ et Python.')}</p><div class="hero-cta"><div><a class="button primary" href="#download">↓ {t('Try the Windows demo','Essayer la démo Windows')}</a><a class="button" href="guide.html">{t('Start building','Commencer à intégrer')} ↗</a></div><small>{t('MIT · Active development · Demo 1.2.0','MIT · En développement · Démo 1.2.0')}</small></div></div>{self.figure('overview-fr' if self.fr else 'overview','CyUI demo — complete workspace, gallery, controls and inspector','Démo CyUI — espace complet, galerie, contrôles et inspecteur',True)}</div></section>
<nav class="chapter-bar" aria-label="{t('Page chapters','Chapitres de la page')}"><div class="wrap chapter-inner">''' + "".join(f'<a href="#{key}"><span>{i:02}</span>{label}</a>' for i,(key,label) in enumerate(chapters,1)) + f'''</div></nav><div class="wrap intro-line"><p>{t('For developers building editors, creative software and technical tools. Share the interface components across your applications; keep each application’s own engine and data.','Pour les développeurs d’éditeurs, de logiciels créatifs et d’outils techniques. Partagez les composants d’interface entre vos applications, tout en gardant leurs moteurs et leurs données propres.')}</p><div class="tech-line"><span>C++17 / C++20</span><span>Python 3.10+</span><span>Dear ImGui ≥ 1.92</span></div></div>''']
        themes = [("overview","Mid grey","Gris moyen",""),("theme-light","Light grey","Gris clair","swatch-light"),("theme-amber","Amber night","Nuit ambrée","swatch-amber"),("theme-violet","Violet","Violet","swatch-violet"),("theme-navy","Navy","Bleu nuit","swatch-navy")]
        controls = ''.join(f'''<button type="button" class="theme-button {cls}" data-theme-image="{self.assets}screenshots/{name}.webp" data-theme-alt="{e(t('CyUI gallery — '+en, 'Galerie CyUI — '+fr))}" aria-pressed="{'true' if i==0 else 'false'}"><span class="theme-dot" aria-hidden="true"></span>{e(t(en,fr))}</button>''' for i,(name,en,fr,cls) in enumerate(themes))
        parts.append(f'''<section class="section wrap" id="foundation" data-chapter>{self.section_head('01',t('A shared visual language','Un langage visuel commun'),'Start with a consistent foundation.','Commencez avec une base cohérente.','Buttons, fields, cards and layouts belong together. Five themes, two densities and semantic color roles carry the same visual language into every module.','Boutons, champs, cartes et dispositions forment un ensemble. Cinq thèmes, deux densités et des rôles de couleurs sémantiques unifient tous les modules.')}<div class="theme-controls" role="group" aria-label="{t('Preview a built-in theme','Prévisualiser un thème intégré')}">{controls}</div>{self.figure('overview','CyUI gallery — Mid grey','Galerie CyUI — Gris moyen',image_id='theme-preview')}<div class="triad"><article><h3>{t('A complete everyday toolkit','Les outils du quotidien')}</h3><p>{t('Forms, tables, navigation, status messages and notifications share the active theme. Ordinary Dear ImGui widgets continue to work alongside CyUI.','Formulaires, tableaux, navigation, états et notifications partagent le thème actif. Les widgets Dear ImGui ordinaires fonctionnent aussi aux côtés de CyUI.')}</p></article><article><h3>{t('Made for dense workspaces','Pensé pour les espaces denses')}</h3><p>{t('Choose compact or comfortable density. Semantic sizing and per-context DPI/font configuration let the host adapt the interface to its displays.','Choisissez une densité compacte ou confortable. Les dimensions sémantiques et les réglages DPI/polices par contexte permettent à l’application d’adapter l’interface.')}</p></article><article><h3>{t('English first. French included.','Anglais par défaut. Français inclus.')}</h3><p>{t('Switch language while retaining widget identities. Extend the shared catalogue with your application’s translations and additional languages.','Changez de langue en conservant l’identité des widgets. Complétez le catalogue partagé avec les traductions et les langues de votre application.')}</p></article></div></section>''')
        parts.append(f'''<section class="section" id="editors" data-chapter><div class="wrap"><div class="split"><div class="copy"><p class="eyebrow">02 / {t('Editor tools','Outils d’édition')}</p><h2>{t('Give every asset a place.','Une place pour chaque ressource.')}</h2><p>{t('Build content browsers with real folder navigation, grid or list views, thumbnails and selection metadata. Connect the same resources to clear, typed details panels.','Construisez des navigateurs de contenu avec une arborescence, des vues en grille ou en liste, des vignettes et les métadonnées de sélection. Reliez les mêmes ressources à des panneaux de propriétés clairs et typés.')}</p><ul class="feature-list"><li>{t('Hierarchical navigation and drag/drop','Navigation hiérarchique et glisser-déposer')}</li><li>{t('Editable, grouped properties','Propriétés éditables et regroupées')}</li><li>{t('Optional search in menus and panels','Recherche optionnelle dans les menus et panneaux')}</li></ul>{self.link(t('Build an editor panel','Créer un panneau d’édition'),self.doc('editors'))}</div>{self.figure('assets','Content browser — folders, thumbnails and selected resource','Navigateur de contenu — dossiers, vignettes et ressource sélectionnée')}</div><div class="image-pair">{self.image_card('inspector-fr' if self.fr else 'inspector','Inspector — material preview and grouped properties','Inspecteur — aperçu de matériau et propriétés regroupées','Details without duplication.','Des propriétés sans duplication.','Strings, choices, toggles and numeric fields, with draft edits and validation. Your application owns the object, the preview and its Undo history.','Chaînes, choix, interrupteurs et champs numériques, avec brouillons et validation. Votre application reste propriétaire de l’objet, de l’aperçu et de l’historique d’annulation.','editors')}{self.image_card('filtering','Quick filtering — property section and nested export menu','Filtrage rapide — section de propriétés et menu d’export imbriqué','Find the control. Keep your focus.','Trouvez le réglage. Gardez le fil.','Search across nested actions or properties. Match English and translated captions, ignore Latin accents, and use Ctrl/Cmd+F or Escape in the focused view.','Cherchez parmi les actions imbriquées ou les propriétés. Retrouvez les libellés anglais ou traduits, sans les accents latins, avec Ctrl/Cmd+F ou Échap dans la vue active.','filtering')}</div><div class="image-pair">{self.image_card('commands','Searchable command palette with shortcuts','Palette de commandes avec recherche et raccourcis','Actions at your fingertips.','Les actions à portée de clavier.','A searchable command palette returns stable action IDs. The host decides which commands are enabled and performs the requested operation.','La palette de commandes renvoie des identifiants d’action stables. L’application décide quelles commandes sont disponibles et exécute l’opération demandée.','editors')}{self.image_card('diagnostics','Diagnostics — bounded log view and navigable messages','Diagnostics — journal à taille limitée et messages navigables','Read what your tools report.','Lisez ce que vos outils signalent.','Display bounded logs and diagnostic lists with severity, filtering and navigation. The example messages shown here are synthetic.','Affichez des journaux à taille limitée et des diagnostics avec niveaux, filtrage et navigation. Les messages présentés ici sont des exemples fictifs.','editors')}</div></div></section>''')
        parts.append(f'''<section class="section media-focus" id="graphs" data-chapter><div class="wrap">{self.section_head('03',t('Canvas / nodes / curves','Canvas / nœuds / courbes'),'Think in connections.','Pensez en connexions.','Compose visual editors from connected cards and pins. Navigation, selection, movement and layout share one canvas foundation; your application owns graph compatibility and execution.','Composez des éditeurs visuels avec des cartes reliées par des ports. Navigation, sélection, déplacement et disposition partagent une base de canvas ; l’application gère la compatibilité et l’exécution du graphe.')}{self.figure('image-graph','Image graph — source, color grade, blur and output previews','Graphe d’images — source, étalonnage, flou et aperçus de sortie')}<p class="note bordered">{t('The demo host prepares these synthetic textures. CyUI displays them inside the nodes; it does not execute image-processing or shader algorithms.','L’application de démonstration prépare ces textures fictives. CyUI les affiche dans les nœuds ; la bibliothèque n’exécute pas les algorithmes de traitement d’image ou les shaders.')}</p><div class="image-pair">{self.image_card('nodes','Blueprint-style graph — connected voice modules and colored pins','Graphe de type blueprint — modules de voix reliés et ports colorés','Visual logic, clearly laid out.','Une logique visuelle bien organisée.','Typed-looking pins, curved links and navigable cards give your graph a readable shape. Pin types, validation and evaluation are supplied by the host.','Ports différenciés, liaisons courbes et cartes navigables donnent une forme lisible à votre graphe. Les types de ports, la validation et l’évaluation viennent de l’application.','data')}{self.image_card('curves','Curve editor — keyframes and Bezier handles','Éditeur de courbes — images clés et poignées de Bézier','Make the movement editable.','Rendez le mouvement éditable.','Edit keyframes, handles and selection with snapping and explicit edit transactions. Connect the proposals to your application’s automation and Undo system.','Modifiez les images clés, poignées et sélections avec alignement et transactions d’édition explicites. Reliez ces propositions à l’automation et à l’historique d’annulation de l’application.','data')}</div></div></section>''')
        parts.append(f'''<section class="section" id="audio" data-chapter><div class="wrap"><div class="split reverse">{self.figure('audio','AudioViews — waveform, logarithmic spectrum, oscilloscope and stereo scope','AudioViews — forme d’onde, spectre logarithmique, oscilloscope et vue stéréo')}<div class="copy"><p class="eyebrow">04 / {t('Audio & data','Audio et données')}</p><h2>{t('Make your signals readable.','Rendez vos signaux lisibles.')}</h2><p>{t('Waveforms, spectra, oscilloscopes and stereo scopes sit alongside familiar knobs, faders and meters. Use the same visual system for creative audio tools and technical analysis.','Formes d’onde, spectres, oscilloscopes et vues stéréo côtoient potentiomètres, faders et indicateurs. Utilisez le même système visuel pour les outils audio créatifs et l’analyse technique.')}</p><p>{t('AudioViews draws data prepared by your application. Audio decoding, FFTs and signal processing remain in your engine.','AudioViews dessine les données préparées par votre application. Le décodage audio, les FFT et le traitement du signal restent dans votre moteur.')}</p>{self.link(t('Explore data views','Explorer les vues de données'),self.doc('data'))}</div></div><div class="image-pair">{self.image_card('plots','Plots — frequency response, histogram and heatmap','Graphiques — réponse en fréquence, histogramme et carte de chaleur','From a series to an overview.','De la série à la vue d’ensemble.','Linear and logarithmic axes, lines, points, steps, bars, histograms and heatmaps. Feed bounded or reduced datasets from your application.','Axes linéaires et logarithmiques, lignes, points, paliers, barres, histogrammes et cartes de chaleur. Fournissez des jeux de données limités ou réduits depuis l’application.','data')}{self.image_card('timeline','Timeline — clip lanes, markers, snapping and playhead','Chronologie — pistes de clips, marqueurs, alignement et tête de lecture','Give time a structure.','Donnez une structure au temps.','Move and trim clips, select time ranges and display markers. Time units, transport, media decoding and project state belong to the host.','Déplacez et ajustez les clips, sélectionnez des plages et affichez des marqueurs. Unités de temps, transport, décodage et état du projet appartiennent à l’application.','data')}</div></div></section>''')
        parts.append(f'''<section class="section code-focus" id="code" data-chapter><div class="wrap"><div class="split reverse">{self.figure('code','Code — syntax-colored source, annotations and native editor','Code — coloration syntaxique, annotations et éditeur natif')}<div class="copy"><p class="eyebrow">05 / {t('Code / editing / diff','Code / édition / différences')}</p><h2>{t('Read, edit, compare.','Lisez, éditez, comparez.')}</h2><p>{t('Use a shared syntax catalogue across source views, the native editor and comparisons. Add annotations or register your own language rules and lexer callbacks.','Utilisez un catalogue syntaxique commun aux vues de source, à l’éditeur natif et aux comparaisons. Ajoutez des annotations ou enregistrez vos règles de langage et vos fonctions d’analyse.')}</p><ul class="feature-list"><li>{t('Native C++ editing with Undo/Redo','Édition C++ native avec annulation/rétablissement')}</li><li>{t('Shared language profiles and shader syntax','Profils de langages partagés et syntaxe des shaders')}</li><li>{t('Unified and side-by-side comparisons','Comparaisons unifiées et côte à côte')}</li></ul>{self.link(t('Code integration guide','Guide d’intégration du code'),self.doc('code'))}</div></div><div class="wide-feature"><div class="feature-description"><h3>{t('Keep both sides in view.','Gardez les deux côtés en vue.')}</h3><p>{t('Aligned rows, highlighted changes and navigation between hunks make revisions easier to read. CyUI displays prepared text comparisons; Git, repository access and merge operations stay in the application.','Lignes alignées, changements surlignés et navigation entre les blocs facilitent la lecture des révisions. CyUI affiche les comparaisons préparées ; Git, l’accès au dépôt et les fusions restent dans l’application.')}</p></div>{self.figure('diff','Diff — side-by-side source comparison and highlighted changes','Diff — comparaison de code côte à côte et changements surlignés')}</div></div></section>''')
        parts.append(f'''<section class="section wrap" id="media" data-chapter>{self.section_head('06',t('Images / viewports / documents','Images / vues / documents'),'The rest of the workspace belongs here, too.','Le reste de l’espace de travail a aussi sa place.','Bring image tools, rendered surfaces and readable documents into the same interface. These modules handle presentation and interaction; the host supplies textures, content and services.','Réunissez outils d’image, surfaces rendues et documents lisibles dans une même interface. Ces modules gèrent l’affichage et les interactions ; l’application fournit textures, contenu et services.')}<div class="image-trio">{self.image_card('images','Images — gradient stops, checkerboard and crop tools','Images — points de dégradé, damier et outils de recadrage','Images & gradients','Images et dégradés','Navigate textures, adjust a crop and edit gradient stops. Decoding and image processing stay in your application.','Parcourez les textures, ajustez un recadrage et modifiez les points de dégradé. Le décodage et le traitement d’image restent dans votre application.','media')}{self.image_card('viewport','Viewport — host texture and 2D transform overlay','Vue de scène — texture de l’application et transformation 2D','Host-rendered viewports','Vues rendues par l’application','An orbit-camera model and transform overlays surround a host-rendered surface. The preview texture is synthetic; CyUI is not a 3D engine.','Un modèle de caméra orbitale et des transformations entourent une surface rendue par l’application. La texture d’aperçu est fictive ; CyUI n’est pas un moteur 3D.','media')}{self.image_card('documents','DocumentViews — Markdown content and a sample conversation','DocumentViews — contenu Markdown et conversation d’exemple','Documents & conversations','Documents et conversations','Render a Markdown subset, code blocks, tables and transcripts. Conversation models, networking and AI providers belong to the host.','Affichez un sous-ensemble Markdown, du code, des tableaux et des conversations. Les modèles de conversation, le réseau et les fournisseurs d’IA appartiennent à l’application.','media')}</div></section>''')
        filters = [('all',t('All','Tous')),('core',t('Foundation','Fondation')),('editor',t('Editors','Éditeurs')),('data',t('Data','Données')),('media',t('Media','Médias')),('integration',t('Web','Web'))]
        cards = []
        for name, group, en, fr, deps in MODULES:
            local_deps = deps.replace('host backend','moteur fourni par l’application').replace('selected modules','modules choisis') if self.fr else deps
            anchor = {'core':'start','editor':'editors','data':'data','media':'media','integration':'web'}[group]
            if name in ('Code', 'CodeEditor', 'Diff'):
                anchor = 'code'
            elif name == 'Nodes':
                anchor = 'data'
            elif name in ('Commands', 'Diagnostics'):
                anchor = 'editors'
            cards.append(f'''<article class="module-card" data-family="{group}"><a href="{self.doc(anchor)}"><h3>{name}</h3></a><p>{e(t(en,fr))}</p><code>CyUI::{name}</code><small>{t('Depends on','Dépend de')} : {e(local_deps)}</small></article>''')
        parts.append(f'''<section class="section breakout" id="modules" data-chapter><div class="wrap">{self.section_head('07',t('Build your own combination','Composez votre ensemble'),'Start with Core. Add what you use.','Partez de Core. Ajoutez ce qui vous sert.','Each C++ module is a separate static-library target. Dependencies are selected automatically; a diff viewer does not bring in a browser or an audio engine.','Chaque module C++ est une cible de bibliothèque statique distincte. Les dépendances sont sélectionnées automatiquement ; une vue de différences n’ajoute ni navigateur ni moteur audio.')}<div class="module-tools"><div class="module-search"><label for="module-query">{t('Find a module','Trouver un module')}</label><div class="search-row"><input id="module-query" type="search" placeholder="{t('Name, feature or dependency…','Nom, fonctionnalité ou dépendance…')}" autocomplete="off" aria-controls="module-catalogue"><button type="button" data-clear-search aria-label="{t('Clear module search','Effacer la recherche de modules')}">×</button></div></div><div class="filter-controls" role="group" aria-label="{t('Module families','Familles de modules')}">''' + ''.join(f'<button type="button" data-module-family="{key}" aria-pressed="{"true" if key=="all" else "false"}">{label}</button>' for key,label in filters) + f'''</div></div><p class="module-count" id="module-count" aria-live="polite">{len(MODULES)} {t('modules shown','modules affichés')}</p><div class="module-grid" id="module-catalogue">{''.join(cards)}</div><p class="empty-state" id="module-empty" hidden>{t('No matching module. Try another term or family.','Aucun module correspondant. Essayez un autre terme ou une autre famille.')}</p><p class="note bordered">{t('Additional opt-in adapters: WebCEF uses a separately supplied CEF SDK/runtime; ImGuizmo uses a host-supplied target. Neither is enabled by CYUI_MODULES=All. The Unreal Editor connector is packaged separately.','Adaptateurs supplémentaires au choix : WebCEF utilise un SDK/runtime CEF fourni séparément ; ImGuizmo utilise une cible fournie par l’application. Aucun des deux n’est activé par CYUI_MODULES=All. Le connecteur Unreal Editor se prépare séparément.')}</p></div></section>''')
        integrations = [
            (t('Native','Natif'),'C++',t('Compile against your host’s existing ImGui target. Core needs C++17; the native CodeEditor and tested CEF adapter use C++20.','Compilez avec la cible ImGui déjà utilisée par votre application. Core requiert C++17 ; CodeEditor natif et l’adaptateur CEF testé utilisent C++20.'),'start'),
            ('Python','imgui-bundle',t('Import optional families explicitly. Models are available without a renderer; Python’s editor has multiline editing and a syntax preview.','Importez explicitement les familles optionnelles. Les modèles sont accessibles sans moteur de rendu ; l’éditeur Python propose l’édition multiligne et un aperçu syntaxique.'),'python'),
            ('Web / CEF','HTML + TypeScript',t('Embed a browser surface through a backend or the optional off-screen CEF adapter. Compile TypeScript in your web app and exchange versioned messages.','Intégrez une surface web via un moteur fourni ou l’adaptateur CEF hors écran. Compilez TypeScript dans votre application web et échangez des messages versionnés.'),'web'),
            ('Unreal Editor',t('An optional connector','Un connecteur optionnel'),t('Embed CyUI in Slate panels inside another plugin. Select the modules you need and share a provider or package a uniquely named copy. Editor-only.','Intégrez CyUI dans des panneaux Slate d’un autre plugin. Choisissez les modules nécessaires et partagez un fournisseur ou préparez une copie au nom unique. Éditeur uniquement.'),'unreal'),
        ]
        parts.append(f'''<section class="section wrap" id="integrations" data-chapter>{self.section_head('08',t('One foundation, several hosts','Une fondation, plusieurs hôtes'),'Your application sets the boundaries.','Votre application définit le cadre.','Keep project models, file access, processing and services in the host. CyUI gives them a consistent presentation, with explicit state and edit proposals.','Gardez les modèles du projet, l’accès aux fichiers, les traitements et les services dans l’application. CyUI leur donne un affichage cohérent, avec un état explicite et des propositions de modification.')}<div class="integrations">''' + ''.join(f'<article class="integration"><span class="integration-type">{e(kind)}</span><h3>{e(title)}</h3><p>{e(text)}</p>{self.link(t("Integration guide","Guide d’intégration"),self.doc(anchor))}</article>' for kind,title,text,anchor in integrations) + f'''</div><div class="code-split"><div><h3>{t('Choose dependencies deliberately.','Choisissez vos dépendances.')}</h3><p>{t('This example links Nodes and Inspector through your existing ImGui target. Their required CyUI dependencies follow automatically.','Cet exemple lie Nodes et Inspector à la cible ImGui existante. Leurs dépendances CyUI nécessaires suivent automatiquement.')}</p><p class="note">{t('CMake ≥ 3.16 · Dear ImGui ≥ 1.92. Integration uses add_subdirectory or FetchContent; there is no installed find_package(CyUI) package.','CMake ≥ 3.16 · Dear ImGui ≥ 1.92. L’intégration utilise add_subdirectory ou FetchContent ; il n’existe pas de paquet installé find_package(CyUI).')}</p></div>{self.block('CMakeLists.txt',CMAKE)}</div><div class="guide-callout"><div><h3>{t('From the gallery to your first panel.','De la galerie à votre premier panneau.')}</h3><p>{t('Read the bilingual integration guide, then follow the detailed API references. The HTML guide and its resources also open locally, without a connection.','Lisez le guide d’intégration bilingue, puis consultez les références détaillées des API. Le guide HTML et ses ressources s’ouvrent aussi localement, sans connexion.')}</p></div>{self.link(t('Open documentation','Ouvrir la documentation'),'guide.html','button')}</div></section>''')
        parts.append(f'''<section class="section breakout" id="download" data-chapter><div class="wrap download-layout"><div class="copy"><p class="eyebrow">09 / {t('Try it. Then build with it.','Essayez. Puis intégrez.')}</p><h2>{t('Explore the real thing.','Explorez la vraie interface.')}</h2><p>{t('The portable gallery lets you try CyUI without compiling. For your own software, use the source and select the modules that fit.','La galerie portable permet d’essayer CyUI sans compiler. Pour votre logiciel, utilisez les sources et choisissez les modules adaptés.')}</p><p class="status-line"><span class="status-dot" aria-hidden="true"></span>{t('Active development · Versioned demo 1.2.0','En développement · Démo versionnée 1.2.0')}</p><p class="note">{t('Screenshots show the gallery built from the current source. The downloadable 1.2.0 demo is a release snapshot and may differ from newer source changes.','Les captures montrent la galerie compilée depuis les sources actuelles. La démo 1.2.0 téléchargeable est un instantané de version qui peut différer des évolutions récentes.')}</p><div class="platforms"><div><h3>Windows x64</h3><p>{t('Portable demo + library','Démo portable + bibliothèque')}</p></div><div><h3>Linux</h3><p>{t('Library source; no demo binary','Sources de la bibliothèque ; aucune démo binaire')}</p></div><div><h3>macOS</h3><p>{t('Library source; no demo binary','Sources de la bibliothèque ; aucune démo binaire')}</p></div></div></div><div><article class="download-card"><p class="eyebrow">{t('Portable gallery','Galerie portable')}</p><h3>CyUI Demo 1.2.0</h3><p>Windows x64 · DirectX 11 · ZIP</p><a class="button primary" href="{ZIP}">↓ {t('Download the demo','Télécharger la démo')}</a>{self.link(t('Release notes','Notes de version'),RELEASE)}<p><small>{t('Extract the entire archive, then run cyui_demo.exe. Use Launch-French.cmd for French. No build tools, Python or separate Visual C++ runtime installation required.','Extrayez toute l’archive, puis lancez cyui_demo.exe. Utilisez Launch-French.cmd pour le français. Aucun outil de compilation, Python ou runtime Visual C++ séparé à installer.')}</small></p></article><p class="note bordered">{t('Windows execution is locally validated. Linux/macOS source targets and CI configuration are present, but this repository’s local evidence does not establish execution on those systems. CEF runtimes and Unreal Engine are supplied separately.','L’exécution Windows est validée localement. Les sources et la configuration CI visent Linux/macOS, mais les vérifications locales du dépôt n’établissent pas leur exécution sur ces systèmes. Les runtimes CEF et Unreal Engine sont fournis séparément.')}</p></div></div></section>''')
        faqs = [
            (t('Is CyUI an application or a library?','CyUI est-il une application ou une bibliothèque ?'),t('CyUI is a themed widget and interface-module library built on Dear ImGui. The downloadable application is its interactive gallery. It does not replace your application’s engine, project model or rendering backend.','CyUI est une bibliothèque de widgets et de modules d’interface basée sur Dear ImGui. L’application téléchargeable est sa galerie interactive. La bibliothèque ne remplace ni le moteur, ni le modèle de projet, ni le moteur de rendu de votre application.')),
            (t('Is this an alpha or beta?','Est-ce une version alpha ou bêta ?'),t('The repository identifies the current library and demo as version 1.2.0 and is under active development. It does not declare an alpha or beta designation. Test the modules and adapters against your host and target platforms before distribution.','Le dépôt identifie la bibliothèque et la démo comme version 1.2.0 et leur développement est actif. Il ne déclare pas de statut alpha ou bêta. Testez les modules et adaptateurs dans votre application et sur vos plateformes avant distribution.')),
            (t('Can I use it in commercial software?','Puis-je l’utiliser dans un logiciel commercial ?'),t('CyUI’s own code and adapters use the MIT license. Keep its copyright and permission notice, together with the licenses of the dependencies you distribute. CEF and Unreal Engine retain their separate terms.','Le code propre à CyUI et ses adaptateurs sont sous licence MIT. Conservez les mentions de copyright et d’autorisation, ainsi que les licences des dépendances distribuées. CEF et Unreal Engine gardent leurs conditions distinctes.')),
            (t('Do I have to use all the modules?','Dois-je utiliser tous les modules ?'),t('No. Begin with Core and explicitly select additional targets. Their dependency closure is linked automatically. WebCEF, ImGuizmo and the Unreal Editor connector are optional integrations with separately supplied dependencies.','Non. Commencez par Core et sélectionnez explicitement les autres cibles. Leurs dépendances nécessaires sont liées automatiquement. WebCEF, ImGuizmo et le connecteur Unreal Editor sont des intégrations optionnelles dont les dépendances sont fournies séparément.')),
            (t('Does the documentation work offline?','La documentation fonctionne-t-elle hors ligne ?'),t('The bilingual HTML guide and this showcase are self-contained static pages. Download the site directory and open index.html or guide.html locally. Advanced source references, GitHub and release downloads need a connection and repository access.','Le guide HTML bilingue et cette vitrine sont des pages statiques autonomes. Téléchargez le dossier site et ouvrez index.html ou guide.html localement. Les références avancées aux sources, GitHub et les téléchargements nécessitent une connexion et l’accès au dépôt.')),
        ]
        parts.append(f'''<section class="section wrap"><div class="faq-layout"><div><p class="eyebrow">{t('Before you start','Avant de commencer')}</p><h2>{t('A few useful answers.','Quelques réponses utiles.')}</h2><p>{t('Scope, platforms and the parts your application keeps.','Périmètre, plateformes et responsabilités de votre application.')}</p></div><div class="faq-list">''' + ''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in faqs) + '</div></div></section></main>')
        return '\n'.join(parts)

    def guide_content(self):
        t = self.t
        topics = [('start',t('1. Start with Core','1. Commencer avec Core')),('editors',t('2. Editor tools','2. Outils d’édition')),('data',t('3. Graphs, audio & data','3. Graphes, audio et données')),('code',t('4. Code & comparison','4. Code et comparaison')),('media',t('5. Images & documents','5. Images et documents')),('filtering',t('6. Filtering & languages','6. Filtres et langues')),('python','7. Python'),('web','8. Web / CEF'),('unreal','9. Unreal Editor'),('platforms',t('10. Platforms & licenses','10. Plateformes et licences'))]
        def reference(filename):
            return self.link(t('Detailed source reference (English)','Référence détaillée dans les sources (anglais)'),REPO+'/blob/main/docs/'+filename)
        sections = []
        sections.append(f'''<section id="start"><h2>{t('1. Start with Core','1. Commencer avec Core')}</h2><p>{t('CyUI compiles against the host application’s Dear ImGui instance. Requirements: Dear ImGui ≥ 1.92, CMake ≥ 3.16 and C++17 for Core. CodeEditor and the tested CEF adapter require C++20. The docking branch is recommended when your application uses docking.','CyUI compile avec l’instance Dear ImGui de l’application hôte. Prérequis : Dear ImGui ≥ 1.92, CMake ≥ 3.16 et C++17 pour Core. CodeEditor et l’adaptateur CEF testé requièrent C++20. La branche docking est recommandée si votre application utilise l’ancrage des fenêtres.')}</p><p>{t('Place the repository in external/CyUI and name the existing ImGui target with CYUI_IMGUI_TARGET. Disable unused Audio and Gallery options: their original defaults are ON. Select only the optional families you need.','Placez le dépôt dans external/CyUI et indiquez la cible ImGui existante avec CYUI_IMGUI_TARGET. Désactivez Audio et Gallery si vous ne les utilisez pas : leurs valeurs par défaut historiques sont ON. Sélectionnez uniquement les familles optionnelles nécessaires.')}</p>{self.block('CMakeLists.txt',CMAKE)}<h3>{t('Initialize once, draw each frame','Initialisez une fois, dessinez à chaque image')}</h3><p>{t('After creating each ImGui context, apply the CyUI configuration and load suitable system or host-supplied fonts. Keep the application’s normal NewFrame/Render lifecycle.','Après la création de chaque contexte ImGui, appliquez la configuration CyUI et chargez des polices système ou fournies par l’application. Conservez le cycle NewFrame/Render habituel de votre application.')}</p>{self.block('C++',CPP)}<p>{t('Use palette() color roles and dp()/style metrics when extending the interface. Stable widget IDs and per-view state preserve selection and edits. CyUI integrates through add_subdirectory or FetchContent; it has no installed find_package(CyUI) package.','Utilisez les rôles de couleurs de palette() et les dimensions dp()/style pour étendre l’interface. Des identifiants stables et un état par vue préservent sélections et modifications. CyUI s’intègre avec add_subdirectory ou FetchContent ; aucun paquet installé find_package(CyUI) n’est fourni.')}</p>{reference('AI_GUIDE.md')}</section>''')
        sections.append(f'''<section id="editors"><h2>{t('2. Editor tools','2. Outils d’édition')}</h2><p>{t('Assets supplies folder trees, grid/list presentation, thumbnail callbacks, search and drag/drop requests. Inspector supplies typed properties, collapsible groups, exact integers, validation and draft editing. Commands returns action IDs from a searchable palette; Diagnostics presents bounded logs and navigable messages.','Assets fournit les arborescences, l’affichage en grille/liste, les fonctions de vignettes, la recherche et les demandes de glisser-déposer. Inspector fournit les propriétés typées, groupes repliables, entiers exacts, validation et brouillons. Commands renvoie les identifiants d’action d’une palette de recherche ; Diagnostics affiche des journaux limités et des messages navigables.')}</p>{self.figure('assets','Assets gallery — resource selection and folder navigation','Galerie Assets — sélection de ressources et navigation dans les dossiers')}<h3>{t('Keep edits transactional','Conservez des modifications transactionnelles')}</h3><p>{t('Editors return proposals with begin, update, commit and cancel phases. Keep original model values during a gesture, validate a committed proposal and record it as one host Undo transaction. Increment the supplied revision when host data changes.','Les éditeurs renvoient des propositions avec les phases begin, update, commit et cancel. Gardez les valeurs d’origine du modèle pendant le geste, validez la proposition terminée et enregistrez-la comme une transaction d’annulation dans l’application. Incrémentez la révision fournie si les données changent.')}</p><p>{t('The host owns asset storage, imports, file operations, selection models, preview generation, validation and Undo. CyUI does not load or save application projects.','L’application gère le stockage, les imports, les opérations sur les fichiers, les modèles de sélection, la génération des aperçus, la validation et l’annulation. CyUI ne charge ni ne sauvegarde les projets de l’application.')}</p>{reference('MODULES.md')}</section>''')
        sections.append(f'''<section id="data"><h2>{t('3. Graphs, audio & data','3. Graphes, audio et données')}</h2><p>{t('Canvas is the common grid/pan/zoom layer. Nodes adds cards, pins and connection requests; Plots adds linear/log series, histograms and heatmaps; Curves adds editable keyframes and handles; Timeline adds lanes and clips. AudioViews uses prepared waveform envelopes and sampled spectra/scopes. Audio supplies knobs, faders and peak/RMS meters.','Canvas est la couche commune de grille, déplacement et zoom. Nodes ajoute cartes, ports et demandes de connexion ; Plots ajoute séries linéaires/logarithmiques, histogrammes et cartes de chaleur ; Curves ajoute images clés et poignées éditables ; Timeline ajoute pistes et clips. AudioViews utilise des enveloppes de formes d’onde préparées et des données de spectres/oscilloscopes. Audio fournit potentiomètres, faders et indicateurs de crête/RMS.')}</p><p>{t('The host supplies graph types, compatibility, validation, processing, interpolation, snapping policy, time units, transport and data reduction. No audio engine, decoder, FFT or shader compiler is linked by these presentation modules.','L’application fournit les types de graphes, la compatibilité, la validation, les traitements, l’interpolation, la politique d’alignement, les unités de temps, le transport et la réduction des données. Ces modules d’affichage n’ajoutent aucun moteur audio, décodeur, FFT ou compilateur de shaders.')}</p>{self.figure('audio','Prepared waveform, spectrum, oscilloscope and stereo data','Forme d’onde, spectre, oscilloscope et données stéréo préparés')}<p class="note">{t('Prepare and cache models when source data changes. Supply visible or bounded data to each view; consult the module guide for limits, reduction helpers and edit contracts.','Préparez et mettez les modèles en cache lorsque les données changent. Fournissez à chaque vue des données visibles ou limitées ; consultez le guide des modules pour les limites, les fonctions de réduction et les contrats d’édition.')}</p>{reference('MODULES.md')}</section>''')
        sections.append(f'''<section id="code"><h2>{t('4. Code & comparison','4. Code et comparaison')}</h2><p>{t('Code owns the shared syntax catalogue, source annotations and extensible language registry. CodeEditor adds the bundled native TextEditor backend with Undo/Redo and advanced editor hooks. Diff displays unified or split prepared text comparisons and provides hunk navigation.','Code gère le catalogue syntaxique commun, les annotations et le registre extensible des langages. CodeEditor ajoute le moteur natif TextEditor intégré, avec annulation/rétablissement et points d’extension avancés. Diff affiche des comparaisons préparées, unifiées ou côte à côte, et permet de naviguer entre les blocs.')}</p><p>{t('Use codeLanguages() and codeLanguageForPath() instead of duplicating a language list in the host. Register declarative rules or a host lexer callback for extensions. Register and unregister outside concurrent rendering; retain callbacks until views no longer use them.','Utilisez codeLanguages() et codeLanguageForPath() au lieu de dupliquer une liste de langages dans l’application. Enregistrez des règles déclaratives ou une fonction d’analyse pour les extensions. Effectuez l’enregistrement et le retrait hors du rendu concurrent ; gardez les fonctions en vie tant que des vues les utilisent.')}</p>{self.figure('diff','Native split diff with aligned rows and highlighted text changes','Diff natif côte à côte avec lignes alignées et changements surlignés')}<p>{t('Git access, history queries, merge actions, language servers, compilation and debugging remain host responsibilities. Python’s editor is a separate multiline editor with a syntax preview; it does not expose all native C++ TextEditor features.','L’accès Git, l’historique, les fusions, les serveurs de langage, la compilation et le débogage relèvent de l’application. L’éditeur Python est un éditeur multiligne distinct avec aperçu syntaxique ; il n’expose pas toutes les fonctions de TextEditor natif en C++.')}</p>{reference('CODE.md')}<br>{reference('DIFF.md')}</section>''')
        sections.append(f'''<section id="media"><h2>{t('5. Images & documents','5. Images et documents')}</h2><p>{t('Images navigates host textures and presents checkerboard, crop and gradient-stop interactions. Viewport wraps a host-rendered surface with an orbit-camera model and transform controls. DocumentViews presents a Markdown subset, tables, code blocks, links and transcripts.','Images permet de parcourir les textures de l’application et propose damier, recadrage et points de dégradé. Viewport entoure une surface rendue par l’application d’un modèle de caméra orbitale et de transformations. DocumentViews affiche un sous-ensemble Markdown, des tableaux, du code, des liens et des conversations.')}</p><p>{t('The host owns textures and their lifetime, image/video decoding, rendering, file links, conversation state and remote services. Use Web for a real browser; DocumentViews is not a browser or a full HTML renderer.','L’application possède les textures et gère leur durée de vie, le décodage image/vidéo, le rendu, les liens de fichiers, l’état des conversations et les services distants. Utilisez Web pour un vrai navigateur ; DocumentViews n’est ni un navigateur ni un moteur HTML complet.')}</p>{self.figure('documents','DocumentViews gallery with a synthetic transcript','Galerie DocumentViews et conversation fictive')}{reference('MODULES.md')}</section>''')
        locale_code = '''cyui::setLocale("fr");
cyui::registerTranslations("fr", {{"app.export", "Exporter"}});
if (cyui::button(cyui::trLabel("app.export", "Export").c_str())) {
    exportDocument();
}'''
        sections.append(f'''<section id="filtering"><h2>{t('6. Filtering & languages','6. Filtres et langues')}</h2><p>{t('Core includes optional TextFilter/filterBox controls for panels and a filterMenu for nested action trees. Each view retains its own query. Matching searches English and translated captions, uses all query words and folds Latin accents. Inspector can accept a shared filter without acquiring another optional dependency.','Core contient les contrôles optionnels TextFilter/filterBox pour les panneaux et filterMenu pour les arbres d’actions imbriqués. Chaque vue garde sa requête. La recherche utilise les libellés anglais et traduits, tous les mots saisis et ignore les accents latins. Inspector peut recevoir un filtre partagé sans ajouter de dépendance optionnelle.')}</p><p>{t('English is the default language and French is built in. Use tr() for text and trLabel() for interactive labels, so switching languages preserves widget identities. Add application messages and extra languages with registerTranslations().','L’anglais est la langue par défaut et le français est intégré. Utilisez tr() pour le texte et trLabel() pour les libellés interactifs afin de conserver l’identité des widgets lors du changement de langue. Ajoutez les messages et langues de l’application avec registerTranslations().')}</p>{self.block('C++',locale_code)}<p>{t('The built-in catalogue translates CyUI controls, not user documents, filenames, source code or arbitrary host labels. Supply appropriate fonts and fallback glyphs. RTL layout, complex shaping, plural rules and locale-specific date/number formatting require host work.','Le catalogue intégré traduit les contrôles CyUI, pas les documents, noms de fichiers, codes sources ou libellés arbitraires de l’application. Fournissez les polices et glyphes de repli adaptés. La mise en page de droite à gauche, la composition complexe, les pluriels et les formats locaux de dates/nombres nécessitent un travail dans l’application.')}</p>{reference('LOCALIZATION.md')}<br>{reference('FILTERING.md')}</section>''')
        sections.append(f'''<section id="python"><h2>7. Python</h2><p>{t('From a local CyUI checkout, install the package. imgui-bundle is a UI dependency; optional data models can be imported without creating a renderer. Python requires version 3.10 or newer.','Depuis une copie locale du dépôt CyUI, installez le paquet. imgui-bundle est une dépendance d’interface ; les modèles de données optionnels peuvent être importés sans créer de moteur de rendu. Python 3.10 ou plus récent est requis.')}</p>{self.block('Shell',PYTHON)}{self.block('Python',PYTHON_UI)}<p>{t('Choose optional families explicitly from cyui_modules. Follow examples/python_modules.py for the real gallery and initialize the host’s ImGui frame/backend normally. Native CodeEditor-specific features are not all mirrored by the Python editor.','Choisissez explicitement les familles optionnelles dans cyui_modules. Consultez examples/python_modules.py pour la vraie galerie et initialisez normalement le contexte et le moteur ImGui de l’application. Les fonctions propres à CodeEditor natif ne sont pas toutes reproduites dans l’éditeur Python.')}</p>{reference('MODULES.md')}</section>''')
        sections.append(f'''<section id="web"><h2>8. Web / CEF</h2><p>{t('Web supplies the browser surface contract, input forwarding, origin policy, versioned messages and theme/localization bridge. WebCEF is an opt-in off-screen Chromium Embedded Framework adapter that paints into a host-owned texture. Compile TypeScript to JavaScript with the web application’s own build.','Web fournit le contrat de surface du navigateur, la transmission des entrées, la politique d’origine, les messages versionnés et la passerelle de thème/localisation. WebCEF est un adaptateur Chromium Embedded Framework hors écran, optionnel, qui dessine dans une texture de l’application. Compilez TypeScript vers JavaScript avec les outils de l’application web.')}</p><p>{t('Supply the exact CEF SDK/runtime for each OS and architecture. The host owns initialization, subprocesses, sandbox policy, runtime packaging, message authorization and texture lifetime. CEF is neither downloaded nor enabled by selecting all ordinary modules.','Fournissez le SDK/runtime CEF exact pour chaque système et architecture. L’application gère l’initialisation, les sous-processus, la politique de bac à sable, le packaging, l’autorisation des messages et la durée de vie des textures. CEF n’est ni téléchargé ni activé par la sélection de tous les modules ordinaires.')}</p><p class="note">{t('The portable Windows demo includes a Web preview, not a working browser runtime. The repository records native/Python CEF round-trip testing on Windows. Linux/macOS adapter packaging has not been locally validated.','La démo Windows portable contient un aperçu Web, sans moteur de navigateur fonctionnel intégré. Le dépôt documente des tests de communication CEF natifs/Python sur Windows. Le packaging de l’adaptateur Linux/macOS n’a pas été validé localement.')}</p>{reference('WEB.md')}</section>''')
        sections.append(f'''<section id="unreal"><h2>9. Unreal Editor</h2><p>{t('The optional connector embeds CyUI in native Slate editor panels. It owns ImGui contexts, input, clipboard, font textures and the Slate renderer. The consuming plugin owns its windows, menus and tool state; merely loading the module creates no tools.','Le connecteur optionnel intègre CyUI dans des panneaux natifs Slate de l’éditeur. Il gère les contextes ImGui, les entrées, le presse-papiers, les textures de polices et le rendu Slate. Le plugin consommateur gère ses fenêtres, menus et états ; le chargement du module ne crée aucun outil.')}</p>{self.block('Shell',UNREAL)}<p>{t('Copy the prepared CyUI directory into your plugin’s Source directory and declare the Editor module and its Build.cs dependency. Several consumers should share one provider, or use uniquely named embedded copies. Read the detailed guide before choosing the layout.','Copiez le dossier CyUI préparé dans le dossier Source de votre plugin, puis déclarez le module Editor et sa dépendance dans Build.cs. Plusieurs consommateurs doivent partager un fournisseur ou utiliser des copies intégrées aux noms uniques. Consultez le guide détaillé avant de choisir la disposition.')}</p><p class="note">{t('This is an Editor-only C++ integration. It is not a UMG, Blueprint or gameplay runtime backend. Unreal Engine is supplied and licensed separately. Local validation was performed on Windows.','Il s’agit d’une intégration C++ réservée à l’éditeur. Ce n’est pas un moteur UMG, Blueprint ou d’interface en jeu. Unreal Engine est fourni et licencié séparément. La validation locale a été effectuée sur Windows.')}</p>{reference('UNREAL.md')}</section>''')
        rows = [('Core / C++',t('Windows build and tests','Compilation et tests Windows'),t('Portable sources; CI configured','Sources portables ; CI configurée'),t('Portable sources; CI configured','Sources portables ; CI configurée')),('Demo 1.2.0',t('Win32 / DirectX 11 binary','Exécutable Win32 / DirectX 11'),t('No demo binary','Aucune démo binaire'),t('No demo binary','Aucune démo binaire')),('WebCEF',t('Build and real page/message tests','Compilation et tests de pages/messages réels'),t('Packaging unverified locally','Packaging non vérifié localement'),t('Packaging unverified locally','Packaging non vérifié localement')),('Unreal Editor',t('Local editor validation','Validation locale dans l’éditeur'),t('No local execution evidence','Aucune validation locale d’exécution'),t('No local execution evidence','Aucune validation locale d’exécution'))]
        sections.append(f'''<section id="platforms"><h2>{t('10. Platforms & licenses','10. Plateformes et licences')}</h2><p>{t('The repository targets Windows, Linux and macOS through the host’s ImGui backend. The table distinguishes source targets from local execution evidence; configured CI alone is not proof of a successful run.','Le dépôt vise Windows, Linux et macOS via le moteur ImGui de l’application. Le tableau distingue les systèmes ciblés par les sources des validations locales ; une configuration CI ne prouve pas à elle seule une exécution réussie.')}</p><div class="table-scroll"><table><thead><tr><th>{t('Component','Composant')}</th><th>Windows</th><th>Linux</th><th>macOS</th></tr></thead><tbody>''' + ''.join('<tr>'+''.join(f'<td>{e(cell)}</td>' for cell in row)+'</tr>' for row in rows) + f'''</tbody></table></div><p>{t('CyUI’s own code, documentation and adapters use MIT. Preserve its notice and all notices for distributed dependencies, including Dear ImGui, stb, TextEditor and the selected syntax engines/data. CEF/Chromium and Unreal Engine retain their separate licenses and distribution requirements.','Le code propre à CyUI, sa documentation et ses adaptateurs sont sous licence MIT. Conservez cette mention et celles des dépendances distribuées, dont Dear ImGui, stb, TextEditor et les moteurs/données syntaxiques sélectionnés. CEF/Chromium et Unreal Engine gardent leurs licences et obligations de distribution distinctes.')}</p><p>{t('The versioned demo is 1.2.0. The repository does not declare an alpha/beta designation and development is active. Validate each selected component and platform before shipping your application.','La démo versionnée est la 1.2.0. Le dépôt ne déclare pas de statut alpha/bêta et le développement est actif. Validez chaque composant et plateforme choisis avant de distribuer votre application.')}</p>{reference('LICENSING.md')}<br>{self.link(t('Third-party notices','Mentions des dépendances'),REPO+'/blob/main/THIRD_PARTY_NOTICES.md')}</section>''')
        return f'''<main class="wrap guide-layout" id="main"><nav class="guide-toc" aria-label="{t('Guide chapters','Chapitres du guide')}"><strong>{t('Integration guide','Guide d’intégration')}</strong>''' + ''.join(f'<a href="#{key}">{label}</a>' for key,label in topics) + f'''</nav><article class="guide-article"><p class="eyebrow">CyUI / Documentation</p><h1>{t('Build on a common foundation.','Construisez sur une base commune.')}</h1><p class="guide-intro">{t('A practical guide to selecting modules, embedding CyUI and keeping the host application in charge. This HTML guide is available in English and French and opens offline.','Un guide pratique pour choisir les modules, intégrer CyUI et garder le contrôle dans l’application hôte. Ce guide HTML est disponible en anglais et français et s’ouvre hors ligne.')}</p><p class="note">{t('The detailed API references currently live in the repository in English. Links to those references are explicitly marked; they require a connection and repository access.','Les références détaillées des API se trouvent actuellement dans le dépôt en anglais. Leurs liens sont signalés explicitement ; ils nécessitent une connexion et l’accès au dépôt.')}</p>''' + '\n'.join(sections) + '</article></main>'

    def render(self):
        title = self.t('CyUI — Modular interfaces for desktop tools','CyUI — Des interfaces modulaires pour vos outils')
        if self.guide:
            title = self.t('CyUI — Integration guide','CyUI — Guide d’intégration')
        description = self.t('A themed, modular Dear ImGui library for C++ and Python. Explore real widgets, node graphs, audio displays, code editors and a portable Windows demo.','Une bibliothèque Dear ImGui thématisée et modulaire pour C++ et Python. Découvrez widgets, graphes, vues audio, éditeurs de code et démo Windows portable.')
        css = hashlib.sha256((SITE/'assets/site.css').read_bytes()).hexdigest()[:12]
        js = hashlib.sha256((SITE/'assets/site.js').read_bytes()).hexdigest()[:12]
        filename = "guide.html" if self.guide else "index.html"
        en = "../"+filename if self.fr else filename
        fr = filename if self.fr else "fr/"+filename
        return f'''<!doctype html>
<!-- Generated by tools/build_showcase.py; edit the generator or site/assets/. -->
<html lang="{self.language}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark"><meta name="theme-color" content="#131518"><meta name="description" content="{e(description)}"><meta name="referrer" content="strict-origin-when-cross-origin"><title>{e(title)}</title><link rel="icon" href="{self.assets}mark.svg" type="image/svg+xml"><link rel="alternate" hreflang="en" href="{en}"><link rel="alternate" hreflang="fr" href="{fr}"><link rel="stylesheet" href="{self.assets}site.css?v={css}"><script src="{self.assets}site.js?v={js}" defer></script></head><body>{self.header()}<noscript><p class="no-script">{self.t('All content and guides are available. Enable JavaScript for image enlargement, theme previews and module filtering.','Tout le contenu et les guides sont accessibles. Activez JavaScript pour agrandir les images, prévisualiser les thèmes et filtrer les modules.')}</p></noscript>{self.guide_content() if self.guide else self.main_content()}{self.footer()}{self.dialog()}</body></html>
'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if generated pages or resource versions are stale")
    args = parser.parse_args()
    outputs = {SITE/("fr/" if language=="fr" else "")/("guide.html" if guide else "index.html"):
        Page(language, guide).render() for language in ("en","fr") for guide in (False,True)}
    for path, content in outputs.items():
        if args.check:
            if not path.is_file() or path.read_text(encoding="utf-8") != content:
                raise SystemExit(f"Stale page: {path.relative_to(ROOT)}; run python tools/build_showcase.py")
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8", newline="\n")
        print(f"{'Checked' if args.check else 'Built'} {path.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
